export type ImportValidationTranslator = (
  key: string,
  values?: Record<string, string | number>,
) => string;

const messages: Record<string, string> = {
  "Title is required": "titleRequired",
  "Date format may not be standard. Use ISO format (YYYY-MM-DD) or year (YYYY)":
    "nonStandardDateFormat",
  "Consider including units (cm, in, etc.) in dimensions":
    "includeDimensionUnits",
  "Accession number will be auto-generated": "accessionNumberAutoGenerated",
  "Source is required": "sourceRequired",
  "Date received is required": "dateReceivedRequired",
  "Invalid date format": "invalidDateFormat",
  "Date is in the future": "dateInFuture",
  "Method is required": "methodRequired",
  "Cost must be a valid number": "invalidCost",
  "Cost cannot be negative": "negativeCost",
  "Accession number is required": "accessionNumberRequired",
  "Invalid cost value": "invalidCostValue",
  "Unknown error": "unknownError",
};

export function getImportValidationCopy(
  message: string,
  translate: ImportValidationTranslator,
): string {
  const key = messages[message];
  if (key) return translate(`untranslatedComponents.importValidation.${key}`);

  const invalidMethodPrefix = "Invalid method. Must be one of: ";
  if (message.startsWith(invalidMethodPrefix)) {
    return translate("untranslatedComponents.importValidation.invalidMethod", {
      methods: message.slice(invalidMethodPrefix.length),
    });
  }

  return message;
}
